import type { AssetMeta, Condition, StoryFlag, WorldPackage } from '../engine/schema';

/**
 * 장르 샘플 세계 2 (v0.87): 다크 판타지 · 현대 초능력 · 회귀물 · 무협 2종(정·사·마 대전, 천하무림대회).
 * 작지만 임무·전투·장면이 서로 이어지도록 만든 맛보기 세계다 — 임무 단계마다 고비(조우·장면)가 있고,
 * 장면이 실패하면 전투로 번지며, 전투에 져도 이야기가 이어진다.
 * 이미지는 앱 내장 그림(stock.*)을 쓴다.
 */
const art = (id: string, n: number, target: { characterId?: string; locationId?: string }, label: string): AssetMeta => ({
  id: `stock.${id}--${n}`, name: `기본 이미지: ${label}`, kind: target.characterId ? 'character' : 'scene', ...target, tags: target.characterId ? ['default'] : [], mime: 'image/svg+xml', size: 0,
});
const manifest = (id: string, name: string): WorldPackage['manifest'] => ({ id: `worldforge.sample-${id}`, type: 'world', name, version: '0.1.0', schemaVersion: '0', author: 'WORLDFORGE', license: 'CC-BY-4.0', contentRating: 'teen', locales: ['ko'] });
/** 엔진만 세우는 플래그 (장면·조우·결정의 결과) */
const ENGINE: Condition = { not: { all: [] } };
const engineFlag = (id: string, when: string): StoryFlag => ({ id, when: `(엔진) ${when}`, requires: ENGINE });

